@import url("https://fonts.googleapis.com/css2?family=Great+Vibes&display=swap");
    :root {
      --cream: #f8efe2;
      --linen: #f3e5d2;
      --oat: #ddcab4;
      --warm-paper: #fff8ec;

      --sage: #75806b;
      --deep-sage: #3d4a3e;
      --forest: #263829;

      --cranberry: #8a2440;
      --cranberry-deep: #65182d;
      --rosewood: #7b4a3e;

      --walnut: #5f3f2e;
      --oak: #9f744f;
      --honeywood: #c2925d;
      --soft-gold: #b98b58;

      --ink: #2b211b;
      --muted: #756456;
      --soft-rule: rgba(95, 63, 46, 0.18);
      --gold-rule: rgba(185, 139, 88, 0.42);

      --serif: "Cormorant Garamond", "Baskerville", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
      --roman: "Cinzel", "Trajan Pro", "Times New Roman", Georgia, serif;
      --sans: "Avenir Next", "Segoe UI", system-ui, sans-serif;

      --shadow: 0 24px 70px rgba(60, 42, 30, 0.16);
      --soft-shadow: 0 16px 44px rgba(60, 42, 30, 0.10);
    }

    * { box-sizing: border-box; }

    html { scroll-behavior: smooth; }

    body {
      min-height: 100vh;
      margin: 0;
      display: flex;
      flex-direction: column;
      font-family: var(--serif);
      color: var(--ink);
      line-height: 1.65;
      background: var(--cream);
    }

    body::before {
      display: none;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    :focus-visible {
      outline: 3px solid var(--cranberry);
      outline-offset: 4px;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: -10rem;
      z-index: 1000;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--warm-paper);
      color: var(--cranberry);
      font-family: var(--sans);
      font-weight: 700;
    }

    .skip-link:focus { top: 1rem; }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 80;
      display: grid;
      grid-template-columns: 1fr auto 1fr;
      align-items: center;
      gap: 1rem;
      padding: 0.9rem clamp(1rem, 4vw, 4rem);
      color: var(--warm-paper);
      background: var(--forest);
      border-bottom: 1px solid rgba(255, 248, 236, 0.34);
      box-shadow: 0 8px 24px rgba(38, 56, 41, 0.18);
    }

    .brand {
      justify-self: start;
      font-family: var(--serif);
      font-size: clamp(1.18rem, 2vw, 1.55rem);
      letter-spacing: 0.08em;
      text-transform: uppercase;
      font-weight: 500;
    }

    .monogram {
      justify-self: center;
      display: grid;
      place-items: center;
      width: 3rem;
      height: 3rem;
      border: 1px solid rgba(255, 248, 236, 0.58);
      border-radius: 999px;
      font-family: var(--serif);
      font-size: 1rem;
      letter-spacing: 0.05em;
      background: rgba(255, 248, 236, 0.06);
    }

    .nav {
      justify-self: end;
      display: flex;
      align-items: center;
      gap: clamp(0.7rem, 1.5vw, 1.3rem);
      font-family: var(--roman);
      font-size: 0.66rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
    }

    .nav a {
      opacity: 0.88;
      border-bottom: 1px solid transparent;
      padding: 0.25rem 0;
    }

    .nav a:hover,
    .nav a:focus-visible {
      opacity: 1;
      border-color: var(--warm-paper);
    }

    .hero-wrap {
      padding: clamp(1rem, 2.2vw, 2rem) clamp(1rem, 3vw, 3rem) 0;
      background: var(--cream);
    }

    .hero-photo {
      position: relative;
      min-height: clamp(520px, 76vh, 900px);
      overflow: hidden;
      border: 1px solid rgba(95, 63, 46, 0.22);
      border-radius: 42px 42px 160px 42px;
      background: var(--sage);
      box-shadow: var(--shadow);
      isolation: isolate;
    }

    .hero-photo::before {
      content: "";
      position: absolute;
      inset: 1rem;
      z-index: 5;
      border: 1px solid rgba(255, 248, 236, 0.62);
      border-radius: 30px 30px 138px 30px;
      pointer-events: none;
    }

    .slide {
      position: absolute;
      inset: 0;
      opacity: 0;
      background-size: cover;
      background-repeat: no-repeat;
      animation: orchardFade 45s infinite;
      transform: scale(1.01);
      filter: saturate(0.98) contrast(1.01) brightness(1.01);
    }

    .slide:nth-child(1) {
      background-image: url("data:image/jpeg;base64,");
      background-position: center 48%;
      animation-delay: 0s;
    }

    .slide:nth-child(2) {
      background-image: url("data:image/jpeg;base64,");
      background-position: center 35%;
      animation-delay: 9s;
    }

    .slide:nth-child(3) {
      background-image: url("data:image/jpeg;base64,");
      background-position: center 43%;
      animation-delay: 18s;
    }

    .slide:nth-child(4) {
      background-image: url("data:image/jpeg;base64,");
      background-position: center 44%;
      animation-delay: 27s;
    }

    .slide:nth-child(5) {
      background-image: url("data:image/jpeg;base64,");
      background-position: center 48%;
      animation-delay: 36s;
    }

    @keyframes orchardFade {
      0% { opacity: 0; transform: scale(1.01); }
      6% { opacity: 1; }
      18% { opacity: 1; }
      25% { opacity: 0; transform: scale(1.045); }
      100% { opacity: 0; transform: scale(1.045); }
    }

    .hero-tint {
      position: absolute;
      inset: 0;
      z-index: 3;
      pointer-events: none;
      background: transparent;
    }

    .photo-progress {
      position: absolute;
      left: 50%;
      bottom: 1.35rem;
      transform: translateX(-50%);
      z-index: 7;
      display: flex;
      gap: 0.5rem;
    }

    .photo-progress span {
      width: 2.5rem;
      height: 0.14rem;
      border-radius: 999px;
      background: rgba(255, 248, 236, 0.8);
      box-shadow: 0 2px 10px rgba(43, 33, 27, 0.25);
    }

    .intro {
      position: relative;
      z-index: 10;
      margin-top: -2.8rem;
      padding: 0 clamp(1rem, 5vw, 5rem) clamp(4rem, 7vw, 6rem);
    }

    .intro-card {
      width: min(1120px, 100%);
      margin: 0 auto;
      position: relative;
      overflow: hidden;
      text-align: center;
      padding: clamp(3rem, 6vw, 5.5rem) clamp(1.2rem, 5vw, 4.5rem);
      border-radius: 34px 34px 130px 34px;
      border: 1px solid var(--gold-rule);
      background: var(--warm-paper);
      box-shadow: var(--shadow);
    }

    .intro-card::before {
      content: "";
      position: absolute;
      inset: 1rem;
      border: 1px solid rgba(95, 63, 46, 0.13);
      border-radius: 24px 24px 110px 24px;
      pointer-events: none;
    }

    .intro-card::after {
      content: "";
      position: absolute;
      left: 50%;
      top: -5rem;
      width: 11rem;
      height: 11rem;
      transform: translateX(-50%);
      border-radius: 50%;
      background: transparent;
      pointer-events: none;
    }

    .crest {
      position: relative;
      z-index: 2;
      margin: 0 auto 1.2rem;
      display: grid;
      place-items: center;
      width: clamp(5rem, 9vw, 7rem);
      height: clamp(5rem, 9vw, 7rem);
      border-radius: 50%;
      border: 1px solid var(--soft-gold);
      color: var(--cranberry);
      font-family: var(--serif);
      font-size: clamp(1.15rem, 2.2vw, 1.6rem);
      letter-spacing: 0.06em;
      background: var(--warm-paper);
      box-shadow: 0 12px 32px rgba(60,42,30,0.10);
    }

    .eyebrow {
      position: relative;
      z-index: 2;
      margin: 0;
      color: var(--cranberry);
      font-family: var(--roman);
      font-size: 0.78rem;
      letter-spacing: 0.24em;
      text-transform: uppercase;
    }

    .formal-line {
      position: relative;
      z-index: 2;
      margin: 0.8rem auto 0;
      color: var(--muted);
      font-style: italic;
      font-size: clamp(1rem, 1.8vw, 1.15rem);
    }

    h1, h2, h3 {
      text-wrap: balance;
    }

    h1 {
      position: relative;
      z-index: 2;
      margin: 1rem 0 0;
      color: var(--forest);
      font-family: var(--serif);
      font-size: clamp(3.8rem, 9vw, 8.4rem);
      font-weight: 400;
      line-height: 0.92;
      letter-spacing: -0.055em;
    }

    .amp {
      display: inline-block;
      margin: 0 0.06em;
      color: var(--cranberry);
      font-style: italic;
      font-size: 0.82em;
      animation: subtleLift 10s ease-in-out infinite;
    }

    @keyframes subtleLift {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-0.1rem); }
    }

    .rule {
      position: relative;
      z-index: 2;
      width: min(680px, 100%);
      margin: 1.55rem auto 0;
      display: grid;
      grid-template-columns: 1fr auto 1fr;
      align-items: center;
      gap: 1rem;
      color: var(--soft-gold);
      font-family: var(--roman);
      font-size: 0.84rem;
      letter-spacing: 0.2em;
      text-transform: uppercase;
    }

    .rule::before,
    .rule::after {
      content: "";
      height: 1px;
      background: rgba(185,139,88,0.7);
    }

    .rule::after {
      background: rgba(185,139,88,0.7);
    }

    .intro-details {
      position: relative;
      z-index: 2;
      margin: 1.25rem auto 0;
      display: flex;
      justify-content: center;
      gap: 0.75rem;
      flex-wrap: wrap;
      color: var(--walnut);
      font-size: clamp(1rem, 1.8vw, 1.16rem);
    }

    .intro-details span {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
    }

    .intro-details span:not(:last-child)::after {
      content: "•";
      color: var(--cranberry);
      opacity: 0.75;
    }

    .intro-copy {
      position: relative;
      z-index: 2;
      max-width: 750px;
      margin: 1.25rem auto 0;
      color: var(--muted);
      font-size: clamp(1.05rem, 1.9vw, 1.22rem);
    }

    .actions {
      position: relative;
      z-index: 2;
      margin-top: 2rem;
      display: flex;
      justify-content: center;
      flex-wrap: wrap;
      gap: 0.85rem;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 3rem;
      padding: 0.78rem 1.28rem;
      border: 1px solid transparent;
      border-radius: 999px;
      font-family: var(--roman);
      font-size: 0.72rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      transition: transform 180ms ease, background 180ms ease, color 180ms ease, border-color 180ms ease;
    }

    .button:hover {
      transform: translateY(-2px);
    }

    .button-primary {
      color: var(--warm-paper);
      background: var(--cranberry);
      border-color: var(--cranberry);
      box-shadow: 0 12px 30px rgba(138, 36, 64, 0.18);
    }

    .button-primary:hover {
      color: var(--warm-paper);
      background: var(--cranberry-deep);
    }

    .button-secondary {
      color: var(--forest);
      background: rgba(255, 248, 236, 0.42);
      border-color: rgba(61, 74, 62, 0.30);
    }

    .button-secondary:hover {
      border-color: var(--sage);
      background: rgba(117, 128, 107, 0.12);
    }

    main {
      position: relative;
      z-index: 4;
    }

    .section {
      position: relative;
      padding: clamp(4rem, 8vw, 7rem) clamp(1rem, 5vw, 5rem);
    }

    .section-panel {
      width: min(1180px, 100%);
      margin: 0 auto;
      position: relative;
      overflow: hidden;
      border-radius: 32px 32px 110px 32px;
      border: 1px solid rgba(95, 63, 46, 0.16);
      background: rgba(255,248,236,0.90);
      box-shadow: var(--soft-shadow);
    }

    .section-panel::before {
      content: "";
      position: absolute;
      inset: 1rem;
      border: 1px solid rgba(95, 63, 46, 0.10);
      border-radius: 22px 22px 90px 22px;
      pointer-events: none;
    }

    .section-content {
      position: relative;
      z-index: 2;
      padding: clamp(2rem, 4.4vw, 4rem);
    }

    .centered {
      text-align: center;
    }

    .section-label {
      margin: 0 0 0.8rem;
      color: var(--cranberry);
      font-family: var(--roman);
      font-size: 0.72rem;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    h2 {
      margin: 0;
      color: var(--forest);
      font-family: var(--serif);
      font-size: clamp(2.25rem, 5vw, 4.8rem);
      line-height: 0.98;
      font-weight: 400;
      letter-spacing: -0.04em;
    }

    .subhead {
      display: block;
      margin-bottom: 0.5rem;
      color: var(--soft-gold);
      font-family: var(--roman);
      font-size: clamp(0.76rem, 1.15vw, 0.92rem);
      letter-spacing: 0.2em;
      text-transform: uppercase;
    }

    .lead {
      max-width: 760px;
      margin: 1.15rem auto 0;
      color: var(--muted);
      font-size: clamp(1.04rem, 1.8vw, 1.19rem);
    }

    .essentials {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
      margin-top: 2.3rem;
    }

    .essential {
      padding: 1.2rem 1rem;
      text-align: center;
      border-radius: 22px 22px 48px 22px;
      border: 1px solid rgba(95, 63, 46, 0.12);
      background: rgba(255, 248, 236, 0.48);
    }

    .essential strong {
      display: block;
      margin-bottom: 0.45rem;
      color: var(--cranberry);
      font-family: var(--roman);
      font-size: 0.68rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
    }

    .essential span {
      display: block;
      color: var(--walnut);
      font-size: 1.28rem;
      line-height: 1.1;
    }

    .split {
      display: grid;
      grid-template-columns: 0.92fr 1.08fr;
      gap: clamp(2rem, 5vw, 4.5rem);
      align-items: center;
    }

    .photo-frame {
      position: relative;
      min-height: 560px;
      overflow: hidden;
      border-radius: 32px 32px 110px 32px;
      border: 1px solid rgba(95, 63, 46, 0.18);
      background-image: url("data:image/jpeg;base64,");
      background-size: cover;
      background-position: center 50%;
      box-shadow: var(--soft-shadow);
    }

    .photo-frame::before {
      content: "";
      position: absolute;
      inset: 1rem;
      border: 1px solid rgba(255, 248, 236, 0.6);
      border-radius: 22px 22px 90px 22px;
      pointer-events: none;
    }

    .copy-block p {
      color: var(--muted);
      font-size: 1.04rem;
    }

    .copy-block .actions {
      justify-content: flex-start;
      margin-top: 1.4rem;
    }

    .button-dark {
      color: var(--warm-paper);
      background: var(--deep-sage);
      border-color: var(--deep-sage);
    }

    .button-dark:hover {
      background: var(--forest);
    }

    .schedule-panel {
      width: min(1180px, 100%);
      margin: 0 auto;
      position: relative;
      overflow: hidden;
      border-radius: 34px 34px 120px 34px;
      border: 1px solid rgba(185, 139, 88, 0.36);
      background: var(--forest);
      color: var(--warm-paper);
      box-shadow: var(--shadow);
    }

    .schedule-panel::before {
      content: "";
      position: absolute;
      inset: 1rem;
      border: 1px solid rgba(255, 248, 236, 0.14);
      border-radius: 24px 24px 100px 24px;
      pointer-events: none;
    }

    .schedule-panel h2 {
      color: var(--warm-paper);
    }

    .schedule-panel .lead {
      color: rgba(255, 248, 236, 0.78);
    }

    .schedule-panel .section-label,
    .schedule-panel .subhead {
      color: var(--oat);
    }

    .timeline {
      display: grid;
      gap: 0.86rem;
      margin-top: 2.3rem;
    }

    .timeline-item {
      display: grid;
      grid-template-columns: 120px 1fr;
      gap: 1rem;
      align-items: baseline;
      padding: 1.12rem 1.2rem;
      border-left: 2px solid rgba(221, 202, 180, 0.5);
      border-radius: 0 18px 38px 0;
      background: rgba(255, 248, 236, 0.06);
    }

    .timeline-time {
      color: var(--oat);
      font-size: 1.42rem;
      white-space: nowrap;
    }

    .timeline-title {
      margin: 0;
      color: var(--warm-paper);
      font-size: 1.06rem;
      font-weight: 700;
    }

    .timeline-desc {
      margin: 0.2rem 0 0;
      color: rgba(255, 248, 236, 0.75);
    }

    .grid-3 {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
      margin-top: 2.3rem;
    }

    .card {
      padding: 1.42rem;
      border-radius: 22px 22px 48px 22px;
      border: 1px solid rgba(95, 63, 46, 0.12);
      background: rgba(255, 248, 236, 0.42);
    }

    .card h3 {
      margin: 0;
      color: var(--cranberry);
      font-size: 1.55rem;
      font-weight: 400;
      line-height: 1.05;
    }

    .card p {
      margin-bottom: 0;
      color: var(--muted);
    }

    .faq-list {
      display: grid;
      gap: 0.8rem;
      margin-top: 2.2rem;
    }

    details {
      padding: 1.1rem 1.2rem;
      border-radius: 18px 18px 40px 18px;
      border: 1px solid rgba(95, 63, 46, 0.12);
      background: rgba(255, 248, 236, 0.44);
    }

    summary {
      cursor: pointer;
      color: var(--forest);
      font-weight: 700;
      list-style: none;
    }

    summary::-webkit-details-marker {
      display: none;
    }

    summary::after {
      content: "+";
      float: right;
      color: var(--cranberry);
      font-size: 1.25rem;
      line-height: 1;
    }

    details[open] summary::after {
      content: "–";
    }

    details p {
      margin: 0.85rem 0 0;
      color: var(--muted);
    }

    .faq-link {
      color: var(--cranberry);
      font-weight: 700;
      text-decoration-line: underline;
      text-decoration-thickness: 1px;
      text-underline-offset: 0.18em;
    }

    .faq-link:hover {
      text-decoration-thickness: 2px;
    }

    .story-panel {
      width: min(1180px, 100%);
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      overflow: hidden;
      border-radius: 34px 34px 120px 34px;
      border: 1px solid rgba(95, 63, 46, 0.16);
      background: rgba(255, 248, 236, 0.88);
      box-shadow: var(--soft-shadow);
    }

    .story-copy {
      padding: clamp(2rem, 4.4vw, 4rem);
    }

    .story-copy p {
      color: var(--muted);
      font-size: 1.04rem;
    }

    .story-photo {
      position: relative;
      min-height: 500px;
      background-image: url("data:image/jpeg;base64,");
      background-size: cover;
      background-position: center 48%;
    }

    .story-photo::after {
      content: "";
      position: absolute;
      inset: 1rem;
      border: 1px solid rgba(255, 248, 236, 0.58);
      border-radius: 22px 22px 90px 22px;
      pointer-events: none;
    }

    .quiet-note {
      width: min(960px, 100%);
      margin: 0 auto;
      text-align: center;
      padding: clamp(2.2rem, 5vw, 4rem);
      border-radius: 34px 34px 110px 34px;
      border: 1px solid rgba(95, 63, 46, 0.16);
      background: rgba(255,248,236,0.92);
      box-shadow: var(--soft-shadow);
    }

    .quiet-note p {
      max-width: 720px;
      margin: 1rem auto 0;
      color: var(--muted);
      font-size: 1.08rem;
    }

    .ottawa-list {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1rem;
      margin-top: 2.3rem;
    }

    .small-card {
      padding: 1.28rem;
      border-radius: 22px 22px 44px 22px;
      border: 1px solid rgba(95, 63, 46, 0.12);
      background: rgba(255, 248, 236, 0.42);
    }

    .small-card h3 {
      margin: 0 0 0.25rem;
      color: var(--cranberry);
      font-size: 1.05rem;
      font-weight: 700;
    }

    .small-card p {
      margin: 0;
      color: var(--muted);
    }

    .small-card a {
      color: var(--cranberry-deep);
      font-weight: 600;
      text-decoration: underline;
      text-decoration-color: rgba(101, 24, 45, 0.35);
      text-decoration-thickness: 1px;
      text-underline-offset: 0.18em;
    }

    .small-card a:hover,
    .small-card a:focus-visible {
      color: var(--cranberry);
      text-decoration-color: currentColor;
    }

    .gallery {
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: 1rem;
      margin-top: 2.3rem;
    }

    .gallery-item {
      min-height: 290px;
      border-radius: 24px 24px 62px 24px;
      border: 1px solid rgba(95, 63, 46, 0.15);
      background-size: cover;
      background-position: center;
      box-shadow: var(--soft-shadow);
    }

    .gallery-item:nth-child(1) {
      grid-column: span 5;
      background-image: url("data:image/jpeg;base64,");
      background-position: center 48%;
    }

    .gallery-item:nth-child(2) {
      grid-column: span 4;
      background-image: url("data:image/jpeg;base64,");
      background-position: center 40%;
    }

    .gallery-item:nth-child(3) {
      grid-column: span 3;
      background-image: url("data:image/jpeg;base64,");
      background-position: center 45%;
    }

    .gallery-item:nth-child(4) {
      grid-column: span 4;
      background-image: url("data:image/jpeg;base64,");
      background-position: center 45%;
    }

    .gallery-item:nth-child(5) {
      grid-column: span 4;
      background-image: url("data:image/jpeg;base64,");
      background-position: center 48%;
    }

    .gallery-item:nth-child(6) {
      grid-column: span 4;
      background-image: url("data:image/jpeg;base64,");
      background-position: center 52%;
    }

    .footer {
      flex-shrink: 0;
      padding: clamp(3rem, 7vw, 5rem) clamp(1rem, 5vw, 5rem);
      text-align: center;
      color: var(--warm-paper);
      background: var(--forest);
      border-top: 1px solid rgba(255, 248, 236, 0.26);
    }

    .footer-mark {
      margin: 0;
      font-size: clamp(2.7rem, 7vw, 5.6rem);
      font-weight: 400;
      line-height: 0.95;
      letter-spacing: -0.04em;
    }

    .footer-details {
      margin: 1.1rem 0 0;
      color: rgba(255, 248, 236, 0.78);
      font-family: var(--roman);
      font-size: 0.76rem;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }

    .footer-note {
      max-width: 640px;
      margin: 1.45rem auto 0;
      color: rgba(255, 248, 236, 0.64);
      font-size: 0.95rem;
    }

    @media (max-width: 1000px) {
      .topbar {
        grid-template-columns: 1fr auto;
      }

      .monogram {
        display: none;
      }

      .nav {
        display: none;
      }

      .intro {
        margin-top: -2rem;
      }

      .essentials,
      .grid-3,
      .split,
      .story-panel,
      .ottawa-list {
        grid-template-columns: 1fr;
      }

      .story-photo {
        min-height: 380px;
        order: -1;
      }

      .gallery {
        grid-template-columns: 1fr;
      }

      .gallery-item,
      .gallery-item:nth-child(n) {
        grid-column: auto;
      }

      .timeline-item {
        grid-template-columns: 1fr;
      }

      .photo-frame {
        min-height: 380px;
      }

      .intro-details {
        display: grid;
        gap: 0.2rem;
      }

      .intro-details span {
        justify-content: center;
      }

      .intro-details span:not(:last-child)::after {
        content: "";
      }
    }

    @media (max-width: 640px) {
      .topbar {
        grid-template-columns: 1fr;
        justify-items: center;
      }

      .brand {
        justify-self: center;
      }

      .hero-photo {
        min-height: 66vh;
        border-radius: 24px 24px 78px 24px;
      }

      .hero-photo::before {
        inset: 0.7rem;
        border-radius: 18px 18px 64px 18px;
      }

      .intro-card,
      .section-panel,
      .schedule-panel,
      .story-panel,
      .quiet-note {
        border-radius: 24px 24px 78px 24px;
      }

      .intro-card::before,
      .section-panel::before,
      .schedule-panel::before {
        inset: 0.7rem;
        border-radius: 16px 16px 64px 16px;
      }

      h1 {
        font-size: clamp(3.2rem, 16vw, 5.6rem);
      }

      .actions {
        flex-direction: column;
        align-items: stretch;
      }

      .button {
        width: 100%;
      }

      .section,
      .intro {
        padding-inline: 1rem;
      }

      .slide:nth-child(1) { background-position: center 48%; }
      .slide:nth-child(2) { background-position: center 35%; }
      .slide:nth-child(3) { background-position: center 38%; }
      .slide:nth-child(4) { background-position: center 42%; }
      .slide:nth-child(5) { background-position: center 47%; }
    }

    @media (prefers-reduced-motion: reduce) {
      html { scroll-behavior: auto; }

      .slide {
        animation: none;
        opacity: 0;
        transform: none;
      }

      .slide:first-child {
        opacity: 1;
      }

      .amp {
        animation: none;
      }

      .button {
        transition: none;
      }

      .button:hover {
        transform: none;
      }
    }

/* Multi-page/final design refinements */
.dc-monogram {
  display: grid;
  place-items: center;
}

.standalone-monogram {
  width: 3rem;
  height: 3rem;
  color: var(--cranberry);
  background: rgba(255, 248, 236, 0.86);
  border: 1px solid rgba(185, 139, 88, 0.65);
  border-radius: 999px;
  box-shadow: 0 12px 28px rgba(95, 63, 46, 0.12);
}

.intro-card h1,
#intro-title {
  display: block;
  white-space: nowrap;
  font-family: "Great Vibes", "Edwardian Script ITC", "Snell Roundhand", "Brush Script MT", cursive;
  font-size: clamp(4.1rem, 10.5vw, 8.7rem);
  line-height: 0.9;
  letter-spacing: 0.005em;
  font-weight: 400;
  color: var(--forest);
  max-width: 100%;
  overflow: visible;
}

.intro-card h1 .amp,
#intro-title .amp {
  font-family: inherit;
  font-size: 0.94em;
  color: var(--cranberry);
  margin: 0 0.035em;
  letter-spacing: 0;
}

.intro-date-venue {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.65rem;
  margin-top: 1.15rem;
  color: var(--soft-gold);
  font-family: var(--roman);
  font-size: 0.74rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.intro-date-venue::before,
.intro-date-venue::after {
  content: "";
  display: block;
  width: clamp(2.5rem, 8vw, 7rem);
  height: 1px;
  background: var(--gold-rule);
}

.map-link,
.venue-link {
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.18em;
  transition: color 160ms ease, text-decoration-color 160ms ease;
}

.map-link:hover,
.map-link:focus-visible,
.venue-link:hover,
.venue-link:focus-visible {
  color: var(--cranberry);
  text-decoration-color: var(--cranberry);
}

/* Connected magazine-style section flow, without making the site feel stripped bare. */
main {
  position: relative;
  flex: 1 0 auto;
  background: var(--cream);
}

.section {
  position: relative;
  padding: clamp(3.8rem, 7vw, 7rem) clamp(1.25rem, 5vw, 5.5rem);
  margin: 0;
}

.section + .section {
  margin-top: 0;
}

.section::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  width: min(980px, 86vw);
  height: 1px;
  transform: translateX(-50%);
  background: rgba(185,139,88,0.32);
}

main > .section:first-child::before,
#venue::before,
#schedule::before,
#travel::before {
  display: none;
}

.section-panel,
.section:nth-of-type(odd) .section-panel,
.section:nth-of-type(even) .section-panel {
  width: min(1180px, 100%);
  max-width: 1180px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

.section-panel::before {
  display: none;
}

.section-content,
.section:nth-of-type(odd) .section-content {
  padding: 0;
}

main > .section:first-child {
  padding-top: clamp(2.5rem, 5vw, 4.5rem);
  padding-bottom: clamp(3rem, 6vw, 5rem);
}

main > .section:first-child .section-panel {
  width: min(1000px, 100%);
  padding: clamp(2.6rem, 5vw, 4.6rem) clamp(1.4rem, 4vw, 3.5rem);
  border-radius: 44px 44px 120px 44px;
  background: rgba(255,248,236,0.58);
  box-shadow: 0 18px 46px rgba(60, 42, 30, 0.07);
}

main > .section:first-child .essentials {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0;
  margin-top: clamp(2rem, 4vw, 3rem);
  border-top: 1px solid rgba(95,63,46,0.14);
  border-bottom: 1px solid rgba(95,63,46,0.14);
}

main > .section:first-child .essential {
  min-width: 150px;
  flex: 1 1 150px;
  padding: 1.15rem 1rem;
  border: 0;
  border-right: 1px solid rgba(95,63,46,0.12);
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

main > .section:first-child .essential:last-child {
  border-right: 0;
}

#venue {
  padding-top: clamp(4rem, 7vw, 7.5rem);
  padding-bottom: clamp(4rem, 7vw, 7.5rem);
  background: transparent;
}

#venue .section-panel {
  width: min(1240px, 100%);
  padding: clamp(1.25rem, 3vw, 2rem) 0;
}

#schedule {
  padding-top: clamp(4.5rem, 8vw, 7.75rem);
  padding-bottom: clamp(4.5rem, 8vw, 7.75rem);
  color: var(--warm-paper);
  background: var(--forest);
}

#schedule .section-panel {
  width: min(1040px, 100%);
  padding: 0;
}

#schedule .section-label,
#schedule h2,
#schedule .lead,
#schedule .subhead {
  color: var(--warm-paper);
}

#schedule .timeline {
  gap: 0;
  margin-top: clamp(2rem, 4vw, 3.2rem);
  border-top: 1px solid rgba(255,248,236,0.22);
  border-bottom: 1px solid rgba(255,248,236,0.22);
}

#schedule .timeline-item {
  border: 0;
  border-bottom: 1px solid rgba(255,248,236,0.14);
  border-radius: 0;
  background: transparent;
  padding: 1.05rem 0;
}

#schedule .timeline-item:last-child {
  border-bottom: 0;
}

#travel {
  background: transparent;
}

.card,
.essential,
.detail-card,
.faq-card,
.travel-card,
.story-card {
  border: 0;
  border-top: 1px solid rgba(95,63,46,0.15);
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.card:hover,
.essential:hover,
.detail-card:hover,
.faq-card:hover,
.travel-card:hover,
.story-card:hover {
  transform: none;
}

#rsvp .section-panel,
#gallery .section-panel {
  padding: clamp(2.75rem, 5vw, 5rem);
  border-radius: 40px 40px 120px 40px;
  background: rgba(255,248,236,0.56);
