/* Home page refinement: keep these sections open and editorial instead of boxed panels. */
main > .section:first-child .section-panel,
.gallery-feature-section .section-panel {
  width: min(1040px, 100%);
  padding: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.story-feature-section .story-copy {
  padding: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.gallery-item {
  cursor: zoom-in;
  appearance: none;
  border: 0;
  font: inherit;
}

.gallery-item:focus-visible {
  outline-offset: 6px;
}

.gallery-lightbox[hidden] {
  display: none;
}

.gallery-lightbox {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 1rem;
  padding: clamp(1rem, 3vw, 2rem);
  background: rgba(38, 56, 41, 0.92);
  color: var(--warm-paper);
}

.gallery-lightbox__bar {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.75rem;
}

.gallery-lightbox__bar p {
  margin: 0 auto 0 0;
  font-family: var(--roman);
  font-size: 0.75rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.gallery-lightbox__control,
.gallery-lightbox__nav {
  border: 1px solid rgba(255, 248, 236, 0.35);
  color: var(--warm-paper);
  background: rgba(255, 248, 236, 0.08);
  cursor: pointer;
}

.gallery-lightbox__control {
  padding: 0.65rem 1rem;
  border-radius: 999px;
  font-family: var(--roman);
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.gallery-lightbox__nav {
  align-self: center;
  width: clamp(2.75rem, 5vw, 4rem);
  height: clamp(2.75rem, 5vw, 4rem);
  border-radius: 999px;
  font-size: clamp(2rem, 4vw, 3.5rem);
  line-height: 1;
}

.gallery-lightbox__scroller {
  min-width: 0;
  min-height: 0;
  overflow: auto;
  border-radius: 18px;
  background: rgba(0, 0, 0, 0.18);
  overscroll-behavior: contain;
}

.gallery-lightbox__image {
  min-width: min(1400px, 92vw);
  min-height: min(920px, 78vh);
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
}

.gallery-lightbox__control:hover,
.gallery-lightbox__nav:hover,
.gallery-lightbox__control:focus-visible,
.gallery-lightbox__nav:focus-visible {
  background: var(--cranberry);
  border-color: var(--cranberry);
}

@media (max-width: 760px) {
  .gallery-lightbox {
    grid-template-columns: 1fr 1fr;
  }

  .gallery-lightbox__scroller {
    grid-column: 1 / -1;
    grid-row: 2;
  }

  .gallery-lightbox__nav {
    grid-row: 3;
    justify-self: center;
  }
}

.map-feature {
