/* Paired cathedral-window wedding party layout */
.wedding-party-grid {
  width: min(980px, 100%);
  margin-inline: auto;
}

.party-card {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto auto;
  align-content: start;
  justify-items: center;
  overflow: visible;
  padding: clamp(1rem, 2.5vw, 1.35rem);
  border-radius: 999px 999px 34px 34px;
  background:
    linear-gradient(var(--warm-paper), var(--warm-paper)) padding-box,
    linear-gradient(180deg, rgba(255, 248, 236, 0.9), rgba(185, 139, 88, 0.72), rgba(101, 24, 45, 0.4)) border-box;
  box-shadow: 0 22px 64px rgba(43, 33, 27, 0.22);
}

.party-card::before {
  inset: 0.7rem;
  border-color: rgba(185, 139, 88, 0.52);
  border-radius: 999px 999px 24px 24px;
}

.party-card::after {
  content: "";
  position: absolute;
  top: 1.05rem;
  bottom: 1.05rem;
  left: 50%;
  z-index: 2;
  width: 1px;
  background: linear-gradient(180deg, rgba(185, 139, 88, 0.42), rgba(185, 139, 88, 0.08) 48%, transparent 48%);
  pointer-events: none;
}

.party-card-photo {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 420px;
  aspect-ratio: 4 / 5;
  min-height: 0;
  overflow: hidden;
  border: 1px solid rgba(185, 139, 88, 0.6);
  border-radius: 999px 999px 26px 26px;
  box-shadow: inset 0 0 0 0.65rem rgba(255, 248, 236, 0.12);
}

.party-card-photo::before,
.party-card-photo::after {
  content: "";
  position: absolute;
  inset-block: 0;
  z-index: 2;
  width: 1px;
  background: rgba(255, 248, 236, 0.42);
  pointer-events: none;
}

.party-card-photo::before { left: 33.333%; }
.party-card-photo::after { right: 33.333%; }

.party-card-photo img {
  width: 100%;
  height: 100%;
  min-height: 0;
  object-fit: cover;
}

.party-card-copy {
  box-sizing: border-box;
  width: min(560px, 100%);
  align-self: start;
  align-items: center;
  justify-content: flex-start;
  padding: clamp(1rem, 2vw, 1.35rem) clamp(1rem, 4vw, 2rem) clamp(1.4rem, 4vw, 2.2rem);
  text-align: center;
}

.party-name-pair {
  white-space: nowrap;
  font-size: clamp(2rem, 4.5vw, 3.5rem) !important;
}

.party-section .party-card p:last-child {
  margin-inline: auto;
}

@media (min-width: 860px) {
  .wedding-party-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: stretch;
  }

  .party-card {
    padding-top: clamp(1.2rem, 2vw, 1.6rem);
  }

  .party-card-copy {
    margin-top: -0.15rem;
  }
}

.party-card-placeholder {
  display: grid;
  place-items: center;
  color: rgba(255, 248, 236, 0.92);
  background:
    radial-gradient(circle at 50% 32%, rgba(255, 248, 236, 0.2), transparent 24%),
